import java.io.BufferedInputStream
import java.util.*

fun main(args: Array<String>) {
    val scanner = Scanner(BufferedInputStream(System.`in`))

    val n = scanner.nextInt()
    val m = scanner.nextInt()

    val foods = mutableMapOf<Int, Int>()
    repeat (m) {
        val food = scanner.nextInt()
        foods[food] = foods.getOrDefault(food, 0) + 1
    }

    var left = 0
    var right = m / n
    while (left < right) {
        val mid = (left + right + 1) / 2
        val canSurviveMid = canSurvive(mid, n, foods)
        if (canSurviveMid) {
            left = mid
        } else {
            right = mid - 1
        }
    }
    println(left)
}

fun canSurvive(day: Int, people: Int, foods: MutableMap<Int, Int>): Boolean {
    var sumPeople = 0L
    for (food in foods) {
        sumPeople += food.value / day
    }

    return sumPeople >= people
}
